{"code": "import openpyxl

wb = openpyxl.load_workbook('./materials/FinancialStatementFY26Q4.xlsx', data_only=False)
print("All sheet names:", wb.sheetnames)

# Find the Segment Results sheet
for name in wb.sheetnames:
    if 'egment' in name or 'egment' in name.lower():
        print(f"Found sheet: {name}")

# Also look for any sheet with segment data
for name in wb.sheetnames:
    ws = wb[name]
    for row in ws.iter_rows(min_row=1, max_row=ws.max_row, values_only=False):
        for c in row:
            if c.value and isinstance(c.value, str) and 'egment' in c.value:
                print(f"Sheet '{name}', cell {c.coordinate}: {c.value}")"}

